SELECT id FROM s_booking
WHERE court_id = #{courtId}
  AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'COMPLETED', 'NO_SHOW', 'ENDED_UNTRACKED')
  AND start_at < #{endAt} AND end_at > #{startAt}
AND id != #{excludedBookingId}
AND session_slot_id != #{excludedSessionSlotId}
ORDER BY id
FOR UPDATE

SELECT * FROM s_booking
WHERE court_id IN
#{courtId}
  AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'COMPLETED', 'NO_SHOW', 'ENDED_UNTRACKED')
  AND start_at < #{endAt} AND end_at > #{startAt}
ORDER BY id FOR UPDATE

SELECT ss.* FROM s_session_slot ss JOIN s_session_slot template ON template.id = #{templateSessionSlotId} WHERE ss.venue_id = template.venue_id AND ss.court_id = template.court_id AND ss.sport_type_id = template.sport_type_id AND ss.slot_date IN
#{date}
AND TIME(CONVERT_TZ(ss.start_at, '+00:00', '+08:00')) = TIME(CONVERT_TZ(template.start_at, '+00:00', '+08:00')) AND TIMESTAMPDIFF(SECOND, ss.start_at, ss.end_at) = TIMESTAMPDIFF(SECOND, template.start_at, template.end_at) ORDER BY ss.id

SELECT * FROM s_session_slot WHERE id IN
#{id}
ORDER BY id FOR UPDATE

SELECT *
FROM s_booking
WHERE venue_id = #{venueId}
  AND source = 'ONLINE'
  AND status = 'CONFIRMED'
  AND start_at <= #{latest}
  AND end_at >= #{earliest}
ORDER BY start_at
